'use strict';
const TeamDiscussion=(()=>{
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const avatar=c=>'<span class="discussion-avatar">'+(/^api\/stats\/avatars\/\d+\/[a-f0-9]+$/.test(c.avatar||'')?'<img src="'+esc(c.avatar)+'" alt="'+esc(c.name)+'的头像" width="36" height="36" loading="lazy">':esc(c.name?.slice(0,1)||'队'))+'</span>';
 const date=stamp=>new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(stamp));
 function init(d){
  const instances=new Map(),drafts=new Map();
  function render(host,kind,entry,visible){if(!host)return;const key=kind+':'+entry.id+':'+(d.getMe()?.id||'guest');let view=instances.get(host.id);if(!view||view.key!==key){if(view){drafts.set(view.key,view.snapshot());view.stop();}view=mount(host,kind,entry,key);instances.set(host.id,view);}view.update(entry,visible);}
  function mount(host,kind,initial,key){
   let saved=drafts.get(key),entry=initial,reply=null,editing=null,attached=false,pending=false,confirmDelete=null,selected=null,mediaTime=0,mediaPage=1,playRequested=false,mediaKey='',watchedKey='',attachmentKey=null,lastList='',lastOptions='',active=false;
   const token={},current=()=>instances.get(host.id)?.instanceToken===token;
   const $=s=>host.querySelector(s),gameMode=kind==='games',base='stats/'+kind+'/'+initial.id;
   host.innerHTML='<div class="discussion-media"><div class="discussion-video-select"><label>训练视频<select data-d="watch-video" aria-label="选择训练视频"></select></label></div><div data-d="media"></div><details class="discussion-video-editor"><summary>添加 / 修改 B 站视频</summary><form data-d="video-form"><label>视频链接或 BV 号<input data-d="video-url" type="text" inputmode="url" maxlength="500" placeholder="https://www.bilibili.com/video/BV…"></label><button class="quiet-btn" type="submit">保存视频链接</button></form></details></div><div class="discussion-heading"><h3>'+(gameMode?'赛后讨论':'训练讨论')+'</h3><span data-d="count" class="muted"></span></div><p class="discussion-hint">分享观察和心得；相同观点可以在评论下回复补充。</p><button type="button" class="quiet-btn" data-action="login">登录队员身份后参与讨论</button><form class="discussion-composer" data-d="form"><div class="discussion-replying" data-d="reply-note" hidden></div><label><span data-d="composer-label">写评论</span><textarea data-d="text" rows="3" maxlength="800" required placeholder="写下你的观察、训练收获或想讨论的问题…"></textarea></label><label class="discussion-attach"><input data-d="attach" type="checkbox">附视频时间点</label><div class="discussion-time-fields" data-d="time-fields" hidden><label>引用视频<select data-d="attach-video" aria-label="评论引用的视频"></select></label><label>时间点<input data-d="time" inputmode="text" placeholder="01:25 或 85" aria-label="视频时间点"></label><label class="discussion-page">分 P<input data-d="page" type="number" min="1" max="1000" value="1" aria-label="视频分 P"></label><small>按播放器显示的进度手动填写，如 01:25 或 85（秒）；发布后可点击定位。</small></div><div class="discussion-submit"><button type="button" class="quiet-btn" data-action="cancel" hidden>取消</button><button class="primary" type="submit" data-d="submit">发布评论</button></div><p data-d="status" class="discussion-status" role="status"></p></form><div class="discussion-list" data-d="list"></div>';
   const games=()=>gameMode?[entry]:entry.games;
   const videos=()=>games().filter(g=>g.video);
   const playable=()=>games().filter(g=>g.videoMeta);
   const findVideo=id=>games().find(g=>g.id===id);
   function updateOptions(){const vs=videos(),ps=playable(),signature=JSON.stringify([vs.map(g=>[g.id,g.name,g.video,g.videoMeta]),selected]);if(signature===lastOptions)return;lastOptions=signature;
    if(!vs.some(g=>g.id===selected)){selected=vs[0]?.id||null;playRequested=false;mediaTime=0;mediaPage=findVideo(selected)?.videoMeta?.page||1;}
    const choices=vs.map(g=>'<option value="'+esc(g.id)+'">'+esc(g.name)+'</option>').join('');$('[data-d="watch-video"]').innerHTML=choices;$('[data-d="watch-video"]').value=selected||'';$('.discussion-video-select').hidden=gameMode||vs.length<2;
    const previous=$('[data-d="attach-video"]').value;$('[data-d="attach-video"]').innerHTML=ps.map(g=>'<option value="'+esc(g.id)+'">'+esc(g.name)+'</option>').join('');$('[data-d="attach-video"]').value=ps.some(g=>g.id===previous)?previous:ps.some(g=>g.id===selected)?selected:ps[0]?.id||'';
    $('.discussion-attach').hidden=!ps.length;if(!ps.length){attached=false;$('[data-d="attach"]').checked=false;$('[data-d="time-fields"]').hidden=true;}
   }
   function media(){const g=gameMode?entry:findVideo(selected);if(g?.videoMeta&&watchedKey&&watchedKey!==g.videoMeta.key){playRequested=false;mediaTime=0;mediaPage=g.videoMeta.page;}if(g?.videoMeta)watchedKey=g.videoMeta.key;const next=active&&g?.videoMeta?JSON.stringify([g.id,g.videoMeta,mediaTime,mediaPage,playRequested]):'';
    if(next!==mediaKey){mediaKey=next;if(next){const frame=document.createElement('iframe');frame.src=BiliVideo.embed(g.videoMeta,mediaTime,mediaPage,playRequested);frame.title=g.name+' · B 站训练视频';frame.allow='autoplay; fullscreen; picture-in-picture';frame.referrerPolicy='strict-origin-when-cross-origin';frame.allowFullscreen=true;const wrap=document.createElement('div');wrap.className='discussion-player';wrap.append(frame);const link=document.createElement('a');link.href=BiliVideo.link(g.videoMeta,mediaTime,mediaPage);link.target='_blank';link.rel='noopener noreferrer';link.textContent='在 B 站打开 ↗';const hint=document.createElement('small');hint.textContent='点击评论时间点可定位；若未自动播放，请点击播放器。';$('[data-d="media"]').replaceChildren(wrap,link,hint);}else $('[data-d="media"]').replaceChildren();}
    if(!next&&active){$('[data-d="media"]').innerHTML=g?.video?'<p class="discussion-video-empty">这条链接可在原站观看。B 站短链接可由管理员重新保存以启用播放器。 <a href="'+esc(g.video)+'" target="_blank" rel="noopener noreferrer">打开视频 ↗</a></p>':(gameMode?'<p class="discussion-video-empty">还没有训练视频，管理员可以在这里添加 B 站链接。</p>':'<p class="discussion-video-empty">训练赛添加视频后，这里可以引用对应的视频时间点。</p>');}
    $('.discussion-video-editor').hidden=!gameMode||!d.canEdit();const input=$('[data-d="video-url"]');if(document.activeElement!==input)input.value=gameMode?entry.video||'':'';
   }
   function message(c,nested=false){const mine=d.getMe()?.id===c.player,stamp=c.video;
    const time=stamp?'<button type="button" class="discussion-timestamp" data-action="seek" data-comment="'+c.id+'"'+(!stamp.available?' disabled':'')+'>▶ '+esc(BiliVideo.formatTime(stamp.seconds))+' · P'+stamp.page+(gameMode?'':' · '+esc(stamp.name))+(!stamp.available?'（视频已更换或移除）':'')+'</button>':'';
    const buttons=c.deleted?(mine?'<button type="button" data-action="restore" data-comment="'+c.id+'">恢复评论</button>':''):(c.parentId===null?'<button type="button" data-action="reply" data-comment="'+c.id+'">回复补充</button>':'')+(mine?'<button type="button" data-action="edit" data-comment="'+c.id+'">编辑</button><button type="button" data-action="delete" data-comment="'+c.id+'">'+(confirmDelete===c.id?'确认删除':'删除')+'</button>':'');
    return '<article class="discussion-message'+(nested?' is-reply':'')+'" data-message="'+c.id+'">'+avatar(c)+'<div class="discussion-message-main"><header><strong>'+esc(c.name)+'</strong><small>#'+c.number+(mine?' · 我':'')+'</small><time>'+esc(date(c.created||c.at))+(c.at>(c.created||c.at)?' · 已编辑':'')+'</time></header><p'+(c.deleted?' class="discussion-deleted"':'')+'>'+esc(c.deleted?'这条评论已删除。':c.text)+'</p>'+time+'<div class="discussion-message-actions">'+buttons+'</div></div></article>';
   }
   function list(){const opened=new Set([...$('[data-d="list"]').querySelectorAll('details[open]')].map(e=>e.dataset.thread));const roots=entry.comments.filter(c=>c.parentId==null);const html=roots.map(c=>{const replies=entry.comments.filter(r=>r.parentId===c.id);return '<div class="discussion-thread">'+message(c)+(replies.length?'<div class="discussion-replies">'+replies.slice(0,3).map(r=>message(r,true)).join('')+(replies.length>3?'<details data-thread="'+c.id+'"'+(opened.has(String(c.id))?' open':'')+'><summary>展开另外 '+(replies.length-3)+' 条回复</summary>'+replies.slice(3).map(r=>message(r,true)).join('')+'</details>':'')+'</div>':'')+'</div>';}).join('')||'<p class="stats-empty">还没有评论，来分享第一条观察吧。</p>';if(html!==lastList){lastList=html;$('[data-d="list"]').innerHTML=html;}
   }
   function composer(){const me=d.getMe();$('[data-d="form"]').hidden=!me;$('[data-action="login"]').hidden=!!me;$('[data-d="submit"]').disabled=pending;$('[data-d="submit"]').textContent=pending?'正在发布…':editing?'保存修改':reply?'发布回复':'发布评论';$('[data-action="cancel"]').hidden=!reply&&!editing;const target=entry.comments.find(c=>c.id===reply);$('[data-d="reply-note"]').hidden=!target;$('[data-d="reply-note"]').textContent=target?'回复 '+target.name+' 的评论':'';$('[data-d="composer-label"]').textContent=editing?'编辑我的评论':reply?'补充你的观点':'写评论';}
   function reset(){reply=editing=null;attached=false;$('[data-d="text"]').value='';$('[data-d="time"]').value='';$('[data-d="attach"]').checked=false;$('[data-d="time-fields"]').hidden=true;$('[data-d="status"]').textContent='';composer();}
   function seek(c){if(!c.video?.available){d.toast('这个时间点关联的视频已更换或移除。');return;}selected=c.video.gameId;playRequested=true;mediaTime=c.video.seconds;mediaPage=c.video.page;watchedKey=c.video.key;updateOptions();mediaKey='';media();$('.discussion-media').scrollIntoView({block:'start',behavior:'smooth'});}
   async function mutate(path,options){if(pending)return null;pending=true;if(current()){composer();$('[data-d="status"]').textContent='';}try{const result=await d.api(path,options);if(result.comments)entry.comments=result.comments;await d.refresh(true);return result;}catch(error){if(current())$('[data-d="status"]').textContent=error.message;d.toast(error.message);return null;}finally{pending=false;if(current()){composer();list();}}}
   $('[data-d="form"]').onsubmit=async event=>{event.preventDefault();if(!d.getMe()||pending)return;const text=$('[data-d="text"]').value.trim();if(!text)return;let video=null;if(attached){const seconds=BiliVideo.parseTime($('[data-d="time"]').value),page=Number($('[data-d="page"]').value),g=findVideo($('[data-d="attach-video"]').value);if(seconds===null||!Number.isInteger(page)||page<1||page>1000||!g?.videoMeta){$('[data-d="status"]').textContent='请选择视频，输入有效时间（如 01:25）和分 P。';return;}video={gameId:g.id,key:g.videoMeta.key,seconds,page};}
    if(video&&attachmentKey&&video.key!==attachmentKey){$('[data-d="status"]').textContent='视频已更换，请重新选择视频时间点。';return;}const body={text,video,...(!editing?{parentId:reply}:{} )};const result=await mutate(base+'/discussion'+(editing?'/'+editing:''),{method:editing?'PUT':'POST',body:JSON.stringify(body)});if(result){if(current()){reset();list();}else drafts.delete(key);d.toast('评论已保存到讨论区。');}
   };
   $('[data-d="attach"]').onchange=event=>{attached=event.target.checked;$('[data-d="time-fields"]').hidden=!attached;if(findVideo(selected)?.videoMeta)$('[data-d="attach-video"]').value=selected;const g=findVideo($('[data-d="attach-video"]').value);if(g){attachmentKey=g.videoMeta.key;$('[data-d="page"]').value=g.videoMeta.page;$('[data-d="time"]').value='';}};
   $('[data-d="attach-video"]').onchange=event=>{attachmentKey=findVideo(event.target.value)?.videoMeta?.key;$('[data-d="page"]').value=findVideo(event.target.value)?.videoMeta?.page||1;};
   $('[data-d="watch-video"]').onchange=event=>{selected=event.target.value;playRequested=false;mediaTime=0;mediaPage=findVideo(selected)?.videoMeta?.page||1;media();};
   $('[data-d="video-form"]').onsubmit=async event=>{event.preventDefault();const input=$('[data-d="video-url"]'),button=event.currentTarget.querySelector('button');button.disabled=true;try{const result=await d.api('stats/games/'+entry.id,{method:'PUT',body:JSON.stringify({video:BiliVideo.extractURL(input.value)})});entry.video=result.game.video;entry.videoMeta=result.game.videoMeta;selected=entry.id;playRequested=false;mediaTime=0;mediaPage=entry.videoMeta?.page||1;lastOptions='';await d.refresh(true);if(current()){updateOptions();media();$('.discussion-video-editor').open=false;}d.toast(entry.video?'视频链接已保存。':'已移除视频链接，原评论会保留。');}catch(error){d.toast(error.message);}finally{button.disabled=false;}};
   host.onclick=async event=>{const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action,c=entry.comments.find(c=>c.id===Number(button.dataset.comment));if(action==='login'){d.login();return;}if(action==='cancel'){reset();return;}if(action==='seek'){if(c)seek(c);return;}if(!d.getMe()){d.login();return;}if(pending||!c)return;
    if(action==='reply'||action==='edit'){reply=action==='reply'?c.id:null;editing=action==='edit'?c.id:null;$('[data-d="text"]').value=editing?c.text:'';attached=!!(editing&&c.video);$('[data-d="attach"]').checked=attached;$('[data-d="time-fields"]').hidden=!attached;if(attached){attachmentKey=c.video.key;$('[data-d="attach-video"]').value=c.video.gameId;$('[data-d="time"]').value=BiliVideo.formatTime(c.video.seconds);$('[data-d="page"]').value=c.video.page;}composer();$('[data-d="form"]').scrollIntoView({block:'center',behavior:'smooth'});$('[data-d="text"]').focus({preventScroll:true});return;}
    if(action==='delete'){if(confirmDelete!==c.id){confirmDelete=c.id;list();return;}confirmDelete=null;await mutate(base+'/discussion/'+c.id,{method:'DELETE'});return;}
    if(action==='restore')await mutate(base+'/discussion/'+c.id,{method:'PUT',body:JSON.stringify({restore:true})});
   };
   return{key,instanceToken:token,snapshot(){return{text:$('[data-d="text"]').value,reply,editing,attached,time:$('[data-d="time"]').value,page:$('[data-d="page"]').value,videoId:$('[data-d="attach-video"]').value,attachmentKey};},stop(){active=false;playRequested=false;media();},update(next,visible){entry=next;active=visible;updateOptions();if(saved){reply=saved.reply;editing=saved.editing;attached=saved.attached&&playable().some(g=>g.id===saved.videoId);attachmentKey=saved.attachmentKey;$('[data-d="text"]').value=saved.text;$('[data-d="attach"]').checked=attached;$('[data-d="time-fields"]').hidden=!attached;$('[data-d="time"]').value=saved.time;$('[data-d="page"]').value=saved.page;if(attached)$('[data-d="attach-video"]').value=saved.videoId;saved=null;}media();composer();const total=entry.comments.filter(c=>!c.deleted).length;$('[data-d="count"]').textContent=total+' 条发言';list();}};
  }
  return{render,stop(host){instances.get(host.id)?.stop();},reset(){instances.clear();drafts.clear();}};
 }
 return{init};
})();
